#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    // Check for required arguments
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    // Parse arguments, ensuring the whole string is consumed
    char *end1 = NULL, *end2 = NULL;
    errno = 0;
    long mode = strtol(argv[1], &end1, 10);
    long n    = strtol(argv[2], &end2, 10);

    if (errno != 0 || end1 == argv[1] || *end1 != '\0' ||
        end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Range checks for the second argument
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Mode handling – the original program treats any mode <= 0 as BAD_MODE
    if (mode <= 0) {
        puts("BAD_MODE");
        return 0;
    }

    double result = 0.0;
    if (mode == 1) {
        // Sum of reciprocals of squares: Σ 1/(i*i)
        for (long i = 1; i <= n; ++i) {
            result += 1.0 / ((double)i * (double)i);
        }
    } else { // mode >= 2
        // 1 + Σ 1/i
        result = 1.0;
        for (long i = 1; i <= n; ++i) {
            result += 1.0 / (double)i;
        }
    }

    printf("%.6f\n", result);
    return 0;
}
